export async function placeOrder(cmd, deps) {
  const { sequelize, orders, customers } = deps;
  return sequelize.transaction(async (t) => {      // commits on success, rolls back on throw
    const customer = await customers.ofId(cmd.customerId, { transaction: t });
    const order = customer.placeOrder(cmd.items);  // the aggregate decides
    await orders.add(order, { transaction: t });
    return order.id;
  });
}
